def form_fields(extra=None, default_from_selected=False):
    options = {"jeu": [("usage", "Usage"), ("qualification", "Qualification")], "service": [("marketing", "Marketing"), ("service_client", "Customer support"), ("interne", "Internal")], "responsable_role": [("veille", "Watch"), ("contenu", "Content"), ("accompagnement", "Support")], "priorite": [("haute", "High"), ("normale", "Normal"), ("basse", "Low")], "statut": [("a_qualifier", "To qualify"), ("en_cours", "In progress"), ("bloque", "Blocked"), ("pret_a_revoir", "Ready for review"), ("termine_interne", "Completed internally"), ("abandonne", "Abandoned")], "revue_manuelle": [("oui", "Yes"), ("non", "No")], "confirmation_manuelle": [("oui", "Yes"), ("non", "No")]}
    labels = {"jeu": "Data set", "case_id": "Case ID", "objectif": "Objective", "critere_fin": "Completion criterion", "service": "Service", "responsable_role": "Responsible role", "priorite": "Priority", "statut": "Status", "prochaine_action": "Next action", "blocage": "Blocker", "veille_ref": "Watch reference", "veille_version": "Watch version", "contenu_ref": "Content reference", "contenu_version": "Content version", "accompagnement_ref": "Support reference", "accompagnement_version": "Support version", "memoire_ref": "Memory reference", "preuve_ref": "Evidence reference", "revue_manuelle": "Manual review", "confirmation_manuelle": "Manual confirmation"}
    result = [{"name": n, "title": labels[n], "type": t, "required": r, **({"options": [{"value": v, "label": label} for v, label in options[n]]} if n in options else {})} for n, t, r in FIELDS]
    if default_from_selected:
        for field in result:
            field["default"] = "non" if field["name"] in {"revue_manuelle", "confirmation_manuelle"} else "{{ state.selected.record." + field["name"] + " }}"
    for name, typ, required, title in extra or []:
        result.append({"name": name, "title": title, "type": typ, "required": required})
    return result


